        # Initialize the SearchArray instance with an array of strings
        self.array = array

    def phrase_freq(self, tokens: List[str], slop=1) -> np.ndarray:
        """
        This function calculates the frequency of a phrase within a SearchArray instance based on the provided tokens and slop.

        Input-Output Arguments
        :param self: SearchArray. An instance of the SearchArray class.
        :param tokens: List[str]. A list of tokens (words) for which the phrase frequency is to be calculated.
        :param slop: int, optional. The maximum distance between tokens in the phrase. Defaults to 1, meaning tokens must be adjacent.
        :return: np.ndarray. An array of phrase frequencies corresponding to the tokens in the SearchArray instance.
        """

        # Check if the slop is 1 and all tokens are unique
        if slop == 1 and len(set(tokens)) == len(tokens):
            # Directly calculate the phrase frequencies using the positions of terms
            phrase_freqs = self._direct_calculate(tokens)
        else:
            # Delegate the calculation to another method that handles different slops or non-unique tokens
            phrase_freqs = self._indirect_calculate(tokens, slop)

        return np.array(phrase_freqs)

    def _direct_calculate(self, tokens: List[str]) -> List[int]:
        # Initialize a dictionary to store the phrase frequencies
        phrase_freqs = {}

        # Iterate over the array to find the phrase frequencies
        for i in range(len(self.array) - len(tokens) + 1):
            phrase = ' '.join(self.array[i:i+len(tokens)])
            if phrase in phrase_freqs:
                phrase_freqs[phrase] += 1
            else:
                phrase_freqs[phrase] = 1

        # Return the phrase frequencies corresponding to the tokens
        return [phrase_freqs.get(' '.join(tokens), 0)]

    def _indirect_calculate(self, tokens: List[str], slop: int) -> List[int]:
        # Initialize a dictionary to store the phrase frequencies
        phrase_freqs = {}

        # Iterate over the array to find the phrase frequencies
        for i in range(len(self.array) - len(tokens) + 1):
            phrase = ' '.join(self.array[i:i+len(tokens)])
            # Check if the phrase is within the slop distance
            if all(self.array[i+j] in tokens for j in range(len(tokens))):
